-- دليل الحضرات: إعداد قاعدة البيانات (الصق هذا كله في Supabase > SQL Editor ثم Run)
create table if not exists hadarat(
  id bigint generated by default as identity primary key,
  name text not null,
  day int not null check (day between 0 and 6),   -- 0=السبت ... 6=الجمعة
  time text not null,                              -- مثل 07:30
  manager text, phone text, dar text, address text, map text,
  updated_at timestamptz not null default now()
);
create table if not exists admins(user_id uuid primary key references auth.users(id) on delete cascade);

alter table hadarat enable row level security;
alter table admins enable row level security;

create policy "الجميع يقرأ الحضرات" on hadarat for select using (true);
create policy "المشرفون فقط يكتبون" on hadarat for all to authenticated
  using (exists (select 1 from admins a where a.user_id = auth.uid()))
  with check (exists (select 1 from admins a where a.user_id = auth.uid()));
create policy "المشرف يرى صفه" on admins for select to authenticated using (user_id = auth.uid());

alter publication supabase_realtime add table hadarat;

-- البيانات الأولية من ملف الإكسيل (33 حضرة)
on conflict (id) do nothing;
select setval(pg_get_serial_sequence('hadarat','id'), (select max(id) from hadarat));

